add_shortcode( 'variation_sales', 'perfectpixel_variation_sales_shortcode' );

function perfectpixel_variation_sales_shortcode( $atts ) {
	global $wpdb;
	$atts = shortcode_atts( array( 'id' => 0 ), $atts );
	$id   = absint( $atts['id'] );
	if ( ! $id ) {
		return '';
	}
	$key  = 'perfectpixel_variation_sales_' . $id;
	$sold = get_transient( $key );
	if ( false === $sold ) {
		$sold = (int) $wpdb->get_var(
			$wpdb->prepare(
				"SELECT SUM(l.product_qty) FROM {$wpdb->prefix}wc_order_product_lookup l
				INNER JOIN {$wpdb->prefix}wc_order_stats s ON s.order_id = l.order_id
				WHERE l.variation_id = %d AND s.status IN ('wc-completed','wc-processing')",
				$id
			)
		);
		set_transient( $key, $sold, HOUR_IN_SECONDS );
	}
	return '<span class="perfectpixel-variation-sales">' . esc_html( number_format_i18n( $sold ) ) . '</span>';
}
